const helpers = this.helpers;
const NL = String.fromCharCode(10);
const GROQ_KEY = $env['GROQ_API_KEY'] || '';
const GEMINI_KEY = $env['GEMINI_API_KEY'] || '';
const GROK_KEY = $env['XAI_API_KEY'] || '';
const providers = [
  { name: 'gemini', url: 'https://cms.example.com/llm/gemini/v1beta/openai/chat/completions', key: GEMINI_KEY, model: 'gemini-3.6-flash' },
  { name: 'groq', url: 'https://cms.example.com/llm/groq/openai/v1/chat/completions', key: GROQ_KEY, model: 'openai/gpt-oss-120b' },
  { name: 'grok', url: 'https://cms.example.com/llm/xai/v1/chat/completions', key: GROK_KEY, model: 'grok-3' },
  { name: 'ollama', url: 'http://ollama:11434/v1/chat/completions', key: '', model: 'qwen3:8b' }
];
const SYS = ['Eres el estratega de candidaturas de el candidato. Escribes cartas de presentacion y ajustes de CV a medida de cada oferta usando UNICAMENTE los datos reales del perfil de abajo. Jamas inventes experiencia, titulos, empresas, metricas ni tecnologias que no aparezcan aqui.','','<<< PON TU PERFIL AQUI: ver automation/n8n/profile.example.md, un dato por linea >>>','== REGLAS DE ESCRITURA ==','1) Usa del perfil SOLO lo que conecta con la oferta, con detalle concreto (proyecto, tecnologia, resultado, cifra como usuarios gestionados, servicios en produccion, clientes reales). Cada afirmacion debe poder rastrearse al perfil.','2) Cuantifica con AL MENOS 2 cifras reales del perfil (p.ej. numero de usuarios gestionados, servicios en produccion, clientes reales, migracion completa a self-hosted). Nada de generalidades vacias.','3) PROHIBIDO el relleno generico y las frases plantilla: no uses emocionado, ansioso, apasionado, excelente oportunidad, encajo perfectamente, equipo altamente cualificado ni similares. Frases concretas y con sustancia.','4) Integra con naturalidad las tecnologias de la oferta que el candidato domina; no inventes las que no tenga. Es junior recien titulado: presentalo como base solida y capacidad demostrada de aprender rapido y llevar proyectos de extremo a extremo, nunca como carencia.','5) Gancho de apertura ESPECIFICO para esta empresa/puesto, no generico. Cierre con disponibilidad (remoto nacional o Asturias) y llamada a la accion.','6) Tono profesional, directo y seguro, primera persona, en el idioma de la oferta (espanol por defecto).','','== FORMATO DE SALIDA (obligatorio) ==','Devuelve EXACTAMENTE estos cuatro bloques, en este orden, sin ningun texto antes, entre o despues, y SIN usar JSON. Cada marcador ocupa su propia linea:','===ASUNTO===','(asunto del email de candidatura, max 80 caracteres, concreto)','===CARTA===','(carta en markdown, 4 parrafos separados por linea en blanco, 280-380 palabras. P1: gancho especifico para esta empresa + puesto al que aplica. P2 y P3: 2-3 logros o proyectos REALES del perfil conectados uno a uno con lo que pide la oferta, con detalle y cifras. P4: encaje + disponibilidad remoto nacional o Asturias + llamada a la accion. Sin fecha ni firma.)','===RESUMEN_CV===','(3-4 lineas para la cabecera del CV adaptadas a esta oferta: titular + SOLO el stack relevante para esta oferta que el candidato ya tenga, sin enumerar todo su stack + 1-2 pruebas reales con cifra)','===AJUSTES_CV===','(lista markdown de 5-7 ajustes ESPECIFICOS y COPIABLES. Cada item empieza por un verbo y da el TEXTO EXACTO a poner. Ejemplos del estilo exigido, cada uno un item: Anade en Experiencia (PROYECTO) - verbo de accion + logro concreto con una cifra y una tecnologia de la oferta; Sube el proyecto mas relevante al principio con su stack; Integra la keyword de la oferta en la seccion Competencias. Prohibido aconsejar en abstracto tipo resalta o mejora sin dar el texto concreto. CRITICO: solo integra keywords de la oferta que el candidato YA tenga en el perfil; NUNCA sugieras anadir como experiencia o habilidad tecnologias que NO aparezcan en el perfil (si la oferta pide p.ej. AWS o Terraform y no estan en el perfil, no las pongas). Si una tecnologia importante de la oferta le falta, ponla como UN item aparte de -a aprender-, sin falsearla como experiencia.)','No escribas nada fuera de esos cuatro bloques.','RECORDATORIO FINAL antes de escribir: NADA de emocionado, ansioso, apasionado, excelente oportunidad ni encajo perfectamente; incluye minimo 2 cifras reales del perfil; cada ajuste de CV debe traer el texto exacto a copiar.'].join(NL);
const o = $json;
const userText = 'OFERTA: ' + (o.title||'') + ' en ' + (o.company||'') + ' (' + (o.location||'') + ', ' + (o.modalidad||'') + ')' + NL + 'ENCAJE IA: ' + (Number(o.score)||0) + '/100 ' + (o.verdict||'') + NL + 'TECNOLOGIAS CLAVE: ' + (Array.isArray(o.keywords)?o.keywords.join(', '):(o.keywords||'')) + NL + 'DESCRIPCION:' + NL + (o.description||'').slice(0,3000);
let content = '', used = 'none';
for (const p of providers) {
  if (p.name !== 'ollama' && !p.key) continue;
  try {
    const headers = { 'Content-Type': 'application/json' };
    if (p.key) headers['Authorization'] = 'Bearer ' + p.key;
    const res = await helpers.httpRequest({ method: 'POST', url: p.url, headers: headers, body: { model: p.model, messages: [{ role: 'system', content: SYS }, { role: 'user', content: userText }], temperature: 0.6, max_tokens: 4096 }, json: true, timeout: 120000 });
    const c = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || '';
    if (c && c.trim().length > 400) { content = c; used = p.name; break; }
    if (c && !content) { content = c; used = p.name; }
  } catch (e) {}
}
if (used === 'none') {
  try { await helpers.httpRequest({ method: 'POST', url: 'https://cms.example.com/tgapi/botYOUR_TELEGRAM_BOT_TOKEN/sendMessage', body: { chat_id: 'YOUR_TELEGRAM_CHAT_ID', text: 'Empleo IA: no se pudo generar la carta/CV, todas las IA caidas o sin credito.' }, json: true }); } catch (e) {}
}
return [{ json: { content: content, _ia: used } }];

const offer = ($('DB leer oferta').first() || { json: {} }).json;
const j = $json;
let raw = (j.content) || (j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || (j.message && j.message.content) || ``;
let gen = { asunto:``, carta_md:``, resumen_cv:``, cv_ajustes_md:`` };
const grab = (name) => { const tag = `===`+name+`===`; const s = raw.indexOf(tag); if (s < 0) return ``; const from = s + tag.length; let end = raw.length; [`ASUNTO`,`CARTA`,`RESUMEN_CV`,`AJUSTES_CV`].forEach(n => { if (n!==name) { const p = raw.indexOf(`===`+n+`===`, from); if (p>=0 && p<end) end = p; } }); return raw.slice(from, end).trim(); };
gen.asunto = grab(`ASUNTO`); gen.carta_md = grab(`CARTA`); gen.resumen_cv = grab(`RESUMEN_CV`); gen.cv_ajustes_md = grab(`AJUSTES_CV`);
if (!gen.carta_md) { try { const a = raw.indexOf(`{`); const b = raw.lastIndexOf(`}`); const o2 = JSON.parse(a>=0&&b>a?raw.slice(a,b+1):raw); gen.asunto = gen.asunto||o2.asunto||``; gen.carta_md = o2.carta_md||``; gen.resumen_cv = gen.resumen_cv||o2.resumen_cv||``; gen.cv_ajustes_md = o2.cv_ajustes_md||``; } catch(e){} }
if (!gen.carta_md) { const _nl = String.fromCharCode(10); gen.carta_md = `(no se pudo interpretar la salida) _ia=`+String(j._ia||`?`)+_nl+_nl+`--- RAW (diagnostico, primeros 1800 car) ---`+_nl+String(raw).slice(0,1800); }
if (!gen.cv_ajustes_md) gen.cv_ajustes_md = `(no generados)`;
const today = new Date().toISOString().slice(0,10);
const slugify = s => (s||``).toString().replace(/[^a-zA-Z0-9]+/g,`-`).replace(/^-+|-+$/g,``).toLowerCase().slice(0,50);
const slug = today + `-` + slugify(offer.company||`empresa`) + `-` + slugify(offer.title||`oferta`);
const clean = s => String(s||``).split(`/`).join(`-`).split(`:`).join(`-`).trim().slice(0,70);
const fileName = (clean(offer.company||`Empresa`) + ` - ` + clean(offer.title||`Oferta`)).slice(0,120) + `.md`;
const folderPath = `/vault/Ofertas/01_Inbox/` + slug;
const filePath = folderPath + `/` + fileName;
const kwStr = Array.isArray(offer.keywords)?offer.keywords.join(`, `):String(offer.keywords||``);
const NL = String.fromCharCode(10);
const yv = s => `'` + String(s==null?``:s).split(`'`).join(``).split(NL).join(` `).trim() + `'`;
const B64 = s => Buffer.from(String(s),`utf8`).toString(`base64`);
const fm = [`---`,`estado: por_revisar`,`empresa: `+yv(offer.company),`puesto: `+yv(offer.title),`ubicacion: `+yv(offer.location),`modalidad: `+yv(offer.modalidad),`fuente: `+yv(offer.source),`url: `+yv(offer.url),`match_score: `+(Number(offer.score)||0),`veredicto: `+yv(offer.verdict),`fecha_deteccion: `+today,`fecha_postulacion: `,`fecha_respuesta: `,`fecha_entrevista: `,`proxima_accion: `,`fecha_proxima: `,`notas: `,`offer_id: `+(Number(offer.id)||0),`tags: [empleo, inbox]`,`---`,``].join(NL);
const indice = fm + [`# `+(offer.title||`Oferta`)+` - `+(offer.company||``),``,`- **Empresa:** `+(offer.company||`-`),`- **Ubicacion:** `+(offer.location||`-`)+` (`+(offer.modalidad||`-`)+`)`,`- **Encaje:** `+(Number(offer.score)||0)+`/100 - `+(offer.verdict||``),`- **Enlace:** `+(offer.url||`-`),``,`## Por que encaja`,(offer.reasons||``),``,`## Tecnologias`,kwStr,``,`## Documentos`,`- [[Carta de presentacion]]`,`- [[Ajustes CV]]`,``,`---`,`### Descripcion (recorte)`,(offer.description||``).slice(0,2500)].join(NL);
const carta = [`# Carta de presentacion`,``,`**Para:** `+(offer.company||``)+`  |  **Puesto:** `+(offer.title||``),`**Asunto:** `+(gen.asunto||((offer.title||`Candidatura`)+` - el candidato `)),`**Fecha:** `+today,``,`---`,``,(gen.carta_md||`(no generada)`),``,`---`,`el candidato  |  tu@email.com  |  TU_TELEFONO  |  example.com  |  github.com/YOUR_USER`].join(NL);
const cvtips = [`# Ajustes de CV para esta oferta`,``,`**`+(offer.company||``)+`** - `+(offer.title||``),``,`---`,``,`## Resumen profesional sugerido`,(gen.resumen_cv||`(no generado)`),``,`## Ajustes a aplicar`,(gen.cv_ajustes_md||`(no generados)`)].join(NL);
const files = [ { name: `_Oferta.md`, contentB64: B64(indice) }, { name: `Carta de presentacion.md`, contentB64: B64(carta) }, { name: `Ajustes CV.md`, contentB64: B64(cvtips) } ];
const esc = v => `'` + String(v==null?``:v).replace(/'/g,`''`) + `'`;
const idNum = Number(offer.id)||0;
const indicePath = folderPath + `/_Oferta.md`;
const cartaPath = folderPath + `/Carta de presentacion.md`;
const gsql = `INSERT INTO empleo.generated (offer_id, asunto, carta_md, resumen_cv, cv_ajustes_md, ia, updated_at) VALUES (`+idNum+`, `+esc(gen.asunto)+`, `+esc(gen.carta_md)+`, `+esc(gen.resumen_cv)+`, `+esc(gen.cv_ajustes_md)+`, `+esc(j._ia)+`, now()) ON CONFLICT (offer_id) DO UPDATE SET asunto=EXCLUDED.asunto, carta_md=EXCLUDED.carta_md, resumen_cv=EXCLUDED.resumen_cv, cv_ajustes_md=EXCLUDED.cv_ajustes_md, ia=EXCLUDED.ia, updated_at=now();`;
const updateSql = `UPDATE empleo.job_offers SET status='generada', vault_path=`+esc(indicePath)+`, cv_path=`+esc(cartaPath)+`, generated_at=now(), updated_at=now() WHERE id=`+idNum+`;` + gsql;
const msg = `Carta y CV generados (`+(Number(offer.score)||0)+`/100)`+NL+(offer.title||`Oferta`)+` - `+(offer.company||``)+NL+(offer.location||``)+` - `+(offer.modalidad||``)+NL+folderPath;
return [{ json: { folderPath: folderPath, files: files, updateSql: updateSql, msg: msg, id: offer.id } }];

const fs = require('fs');
fs.mkdirSync($json.folderPath, { recursive: true });
for (const f of ($json.files || [])) { fs.writeFileSync($json.folderPath + '/' + f.name, Buffer.from(f.contentB64, 'base64')); }
return [{ json: $json }];

