const fs = require('fs');
const offer = $('DB leer aplicar').item.json;
const id = Number(offer.id) || 0;
const NL = String.fromCharCode(10);
const vp = offer.vault_path || ``;
let newPath = vp;
let info = ``;
try {
  if (!vp) { info = `sin vault_path en BD (no se genero?)`; }
  else if (vp.indexOf('/01_Inbox/') === -1) { info = `no esta en 01_Inbox: ` + vp; }
  else {
    const oldFolder = vp.slice(0, vp.lastIndexOf('/'));
    const newFolder = oldFolder.split('/01_Inbox/').join('/02_Postuladas/');
    if (!fs.existsSync(oldFolder)) { info = `carpeta no encontrada: ` + oldFolder; }
    else {
      fs.mkdirSync(newFolder.slice(0, newFolder.lastIndexOf('/')), { recursive: true });
      try { fs.renameSync(oldFolder, newFolder); } catch (e1) { fs.cpSync(oldFolder, newFolder, { recursive: true }); fs.rmSync(oldFolder, { recursive: true, force: true }); }
      newPath = newFolder + '/' + vp.slice(vp.lastIndexOf('/')+1);
      const hoy = new Date().toISOString().slice(0,10);
      try {
        const idx = newFolder + '/_Oferta.md';
        const target = fs.existsSync(idx) ? idx : newPath;
        const txt = fs.readFileSync(target, 'utf8');
        const lines = txt.split(NL).map(L => L.indexOf('estado:') === 0 ? 'estado: postulada' : (L.indexOf('fecha_postulacion:') === 0 ? 'fecha_postulacion: ' + hoy : L));
        fs.writeFileSync(target, lines.join(NL));
      } catch (e2) {}
      info = `movida a 02_Postuladas`;
    }
  }
} catch (e) { info = `ERROR al mover: ` + (e && e.message ? e.message : String(e)); }
const esc = v => `'` + String(v == null ? `` : v).replace(/'/g, `''`) + `'`;
const sql = `INSERT INTO empleo.applications (offer_id,url,company,title,channel,stage,applied_at,proxima_accion,fecha_proxima,updated_at) SELECT id,url,company,title,'telegram','postulada',now(),'Hacer seguimiento (sin respuesta)',(current_date + 7),now() FROM empleo.job_offers WHERE id=` + id + ` AND NOT EXISTS (SELECT 1 FROM empleo.applications WHERE offer_id=` + id + `); UPDATE empleo.applications SET applied_at=COALESCE(applied_at,now()), fecha_proxima=COALESCE(fecha_proxima,(current_date + 7)), proxima_accion=COALESCE(NULLIF(proxima_accion,''),'Hacer seguimiento (sin respuesta)'), updated_at=now() WHERE offer_id=` + id + `; UPDATE empleo.job_offers SET status='aplicada', applied_at=now(), vault_path=` + esc(newPath) + `, updated_at=now() WHERE id=` + id + `;`;
const msg = `Aplicada: ` + (offer.title||`Oferta`) + ` - ` + (offer.company||``) + NL + `Ubicacion: ` + (offer.location||``) + NL + info;
return [{ json: { updateSql: sql, msg: msg } }];

const fs = require('fs');
const offer = $('DB leer descartar').item.json;
const id = Number(offer.id) || 0;
const NL = String.fromCharCode(10);
const vp = offer.vault_path || ``;
let newPath = vp;
let info = ``;
try {
  const src = vp.indexOf('/01_Inbox/') !== -1 ? '/01_Inbox/' : (vp.indexOf('/02_Postuladas/') !== -1 ? '/02_Postuladas/' : null);
  if (!vp) { info = `sin vault_path en BD`; }
  else if (!src) { info = `no esta en Inbox/Postuladas: ` + vp; }
  else {
    const oldFolder = vp.slice(0, vp.lastIndexOf('/'));
    const newFolder = oldFolder.split(src).join('/03_Descartadas/');
    if (!fs.existsSync(oldFolder)) { info = `carpeta no encontrada: ` + oldFolder; }
    else {
      fs.mkdirSync(newFolder.slice(0, newFolder.lastIndexOf('/')), { recursive: true });
      try { fs.renameSync(oldFolder, newFolder); } catch (e1) { fs.cpSync(oldFolder, newFolder, { recursive: true }); fs.rmSync(oldFolder, { recursive: true, force: true }); }
      newPath = newFolder + '/' + vp.slice(vp.lastIndexOf('/')+1);
      info = `movida a 03_Descartadas`;
    }
  }
} catch (e) { info = `ERROR al mover: ` + (e && e.message ? e.message : String(e)); }
const esc = v => `'` + String(v == null ? `` : v).replace(/'/g, `''`) + `'`;
const sql = `UPDATE empleo.job_offers SET status='descartada', vault_path=` + esc(newPath) + `, updated_at=now() WHERE id=` + id + `;`;
const msg = `Descartada: ` + (offer.title||`Oferta`) + ` - ` + (offer.company||``) + NL + info;
return [{ json: { updateSql: sql, msg: msg } }];
